CREATE TABLE IF NOT EXISTS pack_reviews(id TEXT PRIMARY KEY,pack_id TEXT NOT NULL REFERENCES packs(id) ON DELETE CASCADE,revision INTEGER NOT NULL,decision TEXT NOT NULL,note TEXT NOT NULL,reviewer_id TEXT NOT NULL REFERENCES users(id),created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS pack_admin_reviews(pack_id TEXT NOT NULL,revision INTEGER NOT NULL,sha256 TEXT NOT NULL,submission TEXT NOT NULL,PRIMARY KEY(pack_id,revision,sha256));
CREATE TABLE IF NOT EXISTS pack_cloud_approvals(pack_id TEXT PRIMARY KEY,revision INTEGER NOT NULL,sha256 TEXT NOT NULL,digests TEXT NOT NULL,status TEXT NOT NULL,actor_id TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS admin_meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS activity_daily(day TEXT NOT NULL,user_id TEXT NOT NULL REFERENCES users(id),practiced INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(day,user_id));
CREATE TABLE IF NOT EXISTS activity_online(user_id TEXT PRIMARY KEY REFERENCES users(id),last_seen INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS activity_transfers(day TEXT PRIMARY KEY,requests INTEGER NOT NULL,bytes INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS review_mail_attempts(created INTEGER NOT NULL);
